import{z as B,x as A,o as t,c as d,q as r,j as o,D as e,d as s,s as l,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"时钟门控与 DVFS","description":"","frontmatter":{"title":"时钟门控与 DVFS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-gating-dvfs.md","filePath":"cs/clock-gating-dvfs.md","lastUpdated":1791063341000}'),c={name:"cs/clock-gating-dvfs.md"};function p(F,a,D,f,S,V){const n=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="时钟门控与-dvfs" tabindex="-1">时钟门控与 DVFS <a class="header-anchor" href="#时钟门控与-dvfs" aria-label="Permalink to &quot;时钟门控与 DVFS&quot;">​</a></h1><div class="epigraph"><p>不翻转的寄存器仍被时钟树扇入；门控切断局部时钟。电压与频率一起降，动态功耗按 $V^2f$ 掉，时序预算必须同步改写。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Weste and Harris, CMOS VLSI Design；Rabaey et al., Digital Integrated Circuits 整理</footer></div><p><a href="/cs/power-dynamic-static">上一课</a>给出 \\(CV^2f\\alpha\\) 与漏电。缺口是两条常用旋钮：<strong>时钟门控</strong>降无效翻转，<strong>DVFS</strong>（动态电压频率调节）降 \\(V\\) 与 \\(f\\)。它们接到 <a href="/cs/clock-skew-cts">CTS</a> 与 <a href="/cs/sta">STA</a>，不是操作系统里随便写一个「省电」标志就结束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流水线里空泡仍让 FF 每拍采样。门控：用锁存或专用门控单元把时钟与使能相与，使能关掉则该簇 FF 不翻转，时钟缓冲下游也可停。缺口是正确性：门控单元必须避免毛刺时钟，且使能相对时钟满足建立，否则引入假边沿。DVFS：电压岛或整核调 \\(V\\)，频率跟 STA 在该电压下的 \\(f_{\\max}\\)。缺口不是新的功耗公式，而是<strong>控制环</strong>与多角时序。</p><h3 id="门控不是异步复位" tabindex="-1">门控不是异步复位 <a class="header-anchor" href="#门控不是异步复位" aria-label="Permalink to &quot;门控不是异步复位&quot;">​</a></h3><p>关掉时钟不会把状态清零；状态冻住。复位策略仍独立。把 clock enable 当成 reset，上电与休眠唤醒的状态机会错。DVFS 降压时漏电也降，但 SRAM 稳定性有最低电压，FIFO RAM 不能无限降。<span class="marginnote">直觉类比：时钟门控像关掉房间的灯——没人活动了（不翻转），但屋里的家具（寄存器里存的值）原样不动。常见误区：初学者容易把「关时钟」当「清零复位」，实际上重新开灯时一切从冻住的地方继续；想让状态归零必须另走复位电路。</span></p><p><span class="marginnote">CA:AQA 讨论功耗与 DVFS。Weste/Harris 给出门控电路。综合器可自动插入 ICG（integrated clock gating）单元，RTL 用 <code>enable</code> 描述即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>RTL：<code>if (en) q &lt;= d;</code> 综合为门控或数据循环 MUX；真门控省时钟电容。层次：细粒度门控面积开销大，粗粒度（整块 FPU）简单。DVFS：查表或硬件环根据负载选 \\((V,f)\\) 对；跨电压域需要电平移位，CDC 仍可能存在（慢时钟与快时钟）。<span class="marginnote">数字实例看 \\(V^2 f\\) 为什么「降压最划算」：电压从 1.0 V 降到 0.8 V、频率不变，动态功耗就是 \\(0.8^2 = 0.64\\)，直接省 36%；若频率也按比例降到 0.8 倍，再乘一个 0.8，只剩约一半功耗——二次方让电压比频率更值钱。</span></p>',10)),(t(),o(i,null,{default:e(()=>[l(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EN%5B%22%E4%BD%BF%E8%83%BD%22%5D%20--%3E%20ICG%5B%22%E6%97%B6%E9%92%9F%E9%97%A8%E6%8E%A7%E5%8D%95%E5%85%83%22%5D%0A%20%20ICG%20--%3E%20FF%5B%22%E5%B1%80%E9%83%A8%20FF%20%E5%81%9C%E7%BF%BB%22%5D%0A%20%20VF%5B%22%E7%94%B5%E5%8E%8B%E9%A2%91%E7%8E%87%E5%AF%B9%22%5D%20--%3E%20STA2%5B%22%E8%AF%A5%E8%A7%92%E4%B8%8B%E7%9A%84%20STA%22%5D%0A%20%20FF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8A%9F%E8%80%97%E5%A2%99%22%5D%0A%20%20STA2%20--%3E%20LATER%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"测试模式常强制开门控，保证扫描移位——后课 DFT 会再提。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"Dennard 缩放下一课解释：过去降压几乎免费跟上频率；墙之后主要靠门控、暗硅与多核。本课先把两个工程旋钮交到设计者手里。异步 FIFO 两端频率可以因 DVFS 独立变，深度与空满仍靠格雷指针，不靠已知相位。",-1)),(t(),o(i,null,{default:e(()=>[l(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E7%9B%91%E6%B5%8B%E8%B4%9F%E8%BD%BD%E9%AB%98%E4%BD%8E%22%5D%20--%3E%20SEL%7B%22%E6%9F%A5%E7%94%B5%E5%8E%8B%E9%A2%91%E7%8E%87%E8%A1%A8%E9%80%89%20(V%2Cf)%20%E5%AF%B9%22%7D%0A%20%20SEL%20--%3E%20SET%5B%22%E5%86%99%E5%85%A5%E7%94%B5%E5%8E%8B%E5%9F%9F%E4%B8%8E%20PLL%20%E6%96%B0%E9%A2%91%E7%8E%87%22%5D%0A%20%20SET%20--%3E%20CHK%7B%22%E6%96%B0%E7%94%B5%E5%8E%8B%E4%B8%8B%E6%97%B6%E5%BA%8F%E4%BB%8D%E6%94%B6%E6%95%9B%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20BACK%5B%22%E5%9B%9E%E8%B0%83%E5%88%B0%E6%9B%B4%E4%BD%8E%E9%A2%91%E7%8E%87%E6%A1%A3%22%5D%0A%20%20BACK%20--%3E%20CHK%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20RUN%5B%22%E7%BB%A7%E7%BB%AD%E8%BF%90%E8%A1%8C%EF%BC%8C%E7%AD%89%E5%BE%85%E4%B8%8B%E4%B8%80%E8%BD%AE%E8%B0%83%E8%8A%82%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">这张图回答「DVFS 为什么是一个闭环而不是一次性设置」：负载变 → 选新 (V,f) → 降压变频 → 还要回头查时序。常见误区是以为「能跑多快就设多快」——电压降了之后，门变慢，原来满足的建立时间可能不再满足，所以每换一档都要按那一角的 STA 重新验收。</span></p><p><span class="marginnote">术语翻译「电平移位」：0.8 V 域输出的「高电平」只有 0.8 V，在旁边 1.0 V 域的眼里可能既不算 0 也不算 1，判决摇摆。电平移位器就是把它重新抬到 1.0 V 域认得的高度的小电路——跨电压域通信必须经过它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计片上稳压器，不写 Linux <code>cpufreq</code> 驱动。不把 GPU 的 SM 级 DVFS 表格抄来。不讨论电池化学。</p><p>后课默认：门控降时钟翻转；DVFS 改 \\(V,f\\) 并重做时序；漏电还要靠阈值与断电。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>门控切断局部时钟，须无毛刺、满足使能时序。</li><li>DVFS 沿 \\(V^2f\\) 下降，受 SRAM 与 STA 约束。</li><li>冻时钟 ≠ 复位。</li><li>出处：Hennessy and Patterson, CA:AQA；Weste and Harris；Rabaey et al.。</li></ul>',7))])}const h=B(c,[["render",p]]);export{C as __pageData,h as default};
